// Kód uređaje za upravljanje relajima preko Wi-Fi
#include <Arduino.h>

#define RELEJ_1 LED_BUILTIN
#define RELEJ_2 D3

#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>
#include <ESP8266mDNS.h>

ESP8266WebServer server(80);

String getPage();

void preklopi_relej(int relej) {
    // Zaviri relaj na zadanom pinu i čekaj 0.5 sekunde
    digitalWrite(relej, HIGH);
    delay(500);
    digitalWrite(relej, LOW);
}

void setup() {
    // Nastartuj Serijsku ploču i dobavi pinove za relaje kao izlazne
    Serial.begin(9600);
    pinMode(RELEJ_1, OUTPUT);
    pinMode(RELEJ_2, OUTPUT);

    // Povezani na Wi-Fi mрежу
    WiFi.begin("A1_586972105", "Suvidol012");

    // Čekaj do癒stećemo do veza с Wi-Fi
    while (WiFi.status() != WL_CONNECTED) {
        delay(1000);
        Serial.println("Connecting to WiFi...");
    }

    // Započni mDNS respondent i dodaj HTTP službu na portu 80
    if (!MDNS.begin("mdv")) {
        Serial.println("Error setting up MDNS responder!");
        while (1) {
            delay(1000);
        }
    }
    Serial.println("mDNS responder started");
    MDNS.addService("http", "tcp", 80);

    // Pristupi URLima
    server.on("/", HTTP_GET, []() {
        server.send(200, "text/html", getPage());
    });

    server.on("/toggle1", HTTP_GET, []() {
        preklopi_relej(RELEJ_1);
        server.send(200, "text/html", getPage());
    });

    server.on("/toggle2", HTTP_GET, []() {
        preklopi_relej(RELEJ_2);
        server.send(200, "text/html", getPage());
    });

    // Zaviri server
    server.begin();
}

void loop() {
    // Obraćuj veza i aktualiziraj mDNS
    server.handleClient();
    MDNS.update();
}

String getPage() {
    // Vrni HTML strani с кнопkama za upravljanje relajima
    String page = "<html lang=\"hr\">\n"
                 "<head>\n"
